-- Synthetic rollback-only regression: run after all migrations in an isolated database.
BEGIN;
INSERT INTO accounts(id,username,display_name,platform_admin) VALUES('00000000-0000-4000-8000-000000000001'::uuid,'scope-test','Synthetic',true);
INSERT INTO schools(id,name) VALUES('00000000-0000-4000-8000-000000000003'::uuid,'Synthetic scope');
INSERT INTO execution_devices(id,name,enabled,credential_generation) VALUES('00000000-0000-4000-8000-000000000004'::uuid,'Synthetic phone',true,1);
INSERT INTO mobile_targets(id,school_id,search_text,created_by,updated_by) VALUES('00000000-0000-4000-8000-000000000005'::uuid,'00000000-0000-4000-8000-000000000003'::uuid,'Synthetic target','00000000-0000-4000-8000-000000000001'::uuid,'00000000-0000-4000-8000-000000000001'::uuid);
INSERT INTO mobile_shared_school_access(device_id,school_id,enabled,revision,updated_by) VALUES('00000000-0000-4000-8000-000000000004'::uuid,'00000000-0000-4000-8000-000000000003'::uuid,true,1,'00000000-0000-4000-8000-000000000001'::uuid);
INSERT INTO mobile_device_target_bindings(id,school_id,device_id,target_id,source,created_by,updated_by) VALUES('00000000-0000-4000-8000-000000000008'::uuid,'00000000-0000-4000-8000-000000000003'::uuid,'00000000-0000-4000-8000-000000000004'::uuid,'00000000-0000-4000-8000-000000000005'::uuid,'school_pool','00000000-0000-4000-8000-000000000001'::uuid,'00000000-0000-4000-8000-000000000001'::uuid);
DO $$ BEGIN IF (SELECT EXISTS(SELECT 1 FROM mobile_usages u WHERE u.school_id='00000000-0000-4000-8000-000000000003'::uuid AND ((u.body->'device_ids' @> jsonb_build_array('00000000-0000-4000-8000-000000000004'::uuid::uuid) AND (u.body->'auto_targets'='true'::jsonb OR EXISTS(SELECT 1 FROM jsonb_array_elements(u.body->'targets') t WHERE t->>'id'='00000000-0000-4000-8000-000000000005'::uuid::uuid::text))) OR EXISTS(SELECT 1 FROM mobile_usage_scopes m WHERE m.usage_id=u.id AND m.device_id='00000000-0000-4000-8000-000000000004'::uuid AND m.target_id='00000000-0000-4000-8000-000000000005'::uuid)))) THEN RAISE EXCEPTION 'Binding-only task unexpectedly requires usage'; END IF; END $$;
INSERT INTO mobile_usages(id,school_id,actor_id,approval,body,confirmed_until,expires_at,approved_by) VALUES('00000000-0000-4000-8000-000000000006','00000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000001','approved','{"scheme":null}',clock_timestamp()-interval '2 days',clock_timestamp()+interval '1 day','00000000-0000-4000-8000-000000000001');
INSERT INTO mobile_v9_scope_grants(id,school_id,stage,device_ids,target_ids,max_calls,expires_at,reason,created_by,resource_revisions) VALUES('00000000-0000-4000-8000-000000000007'::uuid,'00000000-0000-4000-8000-000000000003'::uuid,'test_send',ARRAY['00000000-0000-4000-8000-000000000004'::uuid],ARRAY['00000000-0000-4000-8000-000000000005'::uuid],5,clock_timestamp()+interval '1 day','Synthetic','00000000-0000-4000-8000-000000000001'::uuid,jsonb_build_object('00000000-0000-4000-8000-000000000004'::uuid::text,1));
INSERT INTO mobile_usage_scopes(scope_id,usage_id,target_id,device_id,resource_snapshot) SELECT '00000000-0000-4000-8000-000000000007'::uuid,'00000000-0000-4000-8000-000000000006'::uuid,'00000000-0000-4000-8000-000000000005'::uuid,'00000000-0000-4000-8000-000000000004'::uuid,jsonb_build_object('device_revision',d.revision,'binding_locator_revision',b.locator_revision,'target_locator_revision',t.locator_revision,'search_text',t.search_text) FROM execution_devices d JOIN mobile_device_target_bindings b ON b.device_id=d.id JOIN mobile_targets t ON t.id=b.target_id;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM mobile_v9_send_policy_versions) THEN RAISE EXCEPTION 'Regression requires no configured policy'; END IF;
 IF EXISTS(SELECT 1 FROM mobile_v9_adapter_releases) OR EXISTS(SELECT 1 FROM mobile_v9_acceptance_runs) OR EXISTS(SELECT 1 FROM mobile_capability_deliveries) OR EXISTS(SELECT 1 FROM mobile_v9_activations) THEN RAISE EXCEPTION 'Unexpected technical records'; END IF;
 IF NOT EXISTS(SELECT to_jsonb(g) FROM mobile_v9_scope_grants g WHERE g.school_id='00000000-0000-4000-8000-000000000003'::uuid AND '00000000-0000-4000-8000-000000000004'::uuid=ANY(g.device_ids) AND ('00000000-0000-4000-8000-000000000005'::uuid=ANY(g.target_ids) OR g.auto_targets) AND ('production_allowlist'='production_allowlist' OR ((g.release_id IS NULL OR g.release_id=NULL::uuid) AND g.stage='production_allowlist')) AND ('00000000-0000-4000-8000-000000000007'::uuid::uuid IS NULL OR g.id='00000000-0000-4000-8000-000000000007'::uuid) AND g.expires_at>clock_timestamp() AND ('production_allowlist'<>'production_allowlist' OR EXISTS(SELECT 1 FROM mobile_usage_scopes us JOIN mobile_usages u ON u.id=us.usage_id WHERE us.scope_id=g.id AND u.approval='approved' AND u.state='active' AND u.expires_at>clock_timestamp() AND EXISTS(SELECT 1 FROM execution_devices ud JOIN mobile_device_target_bindings ub ON ub.device_id=ud.id JOIN mobile_targets ut ON ut.id=ub.target_id WHERE ud.id='00000000-0000-4000-8000-000000000004'::uuid AND ut.id='00000000-0000-4000-8000-000000000005'::uuid AND ub.school_id='00000000-0000-4000-8000-000000000003'::uuid AND us.resource_snapshot=jsonb_build_object('device_revision',ud.revision,'binding_locator_revision',ub.locator_revision,'target_locator_revision',CASE WHEN ub.search_text_override IS NULL THEN ut.locator_revision ELSE NULL END,'search_text',coalesce(ub.search_text_override,ut.search_text))))) AND NOT EXISTS(SELECT 1 FROM mobile_v9_scope_revocations r WHERE r.grant_id=g.id) AND (NOT (g.resource_revisions ? '00000000-0000-4000-8000-000000000004'::uuid::uuid::text) OR (g.resource_revisions->>'00000000-0000-4000-8000-000000000004'::uuid::uuid::text)::bigint=coalesce((SELECT revision FROM mobile_shared_school_access WHERE device_id='00000000-0000-4000-8000-000000000004'::uuid AND school_id='00000000-0000-4000-8000-000000000003'::uuid AND enabled),0)) ORDER BY g.created_at DESC,g.id DESC LIMIT 1) THEN RAISE EXCEPTION 'Business-only scope not effective'; END IF;
 IF NOT (SELECT EXISTS(SELECT 1 FROM mobile_usages u WHERE u.school_id='00000000-0000-4000-8000-000000000003'::uuid AND ((u.body->'device_ids' @> jsonb_build_array('00000000-0000-4000-8000-000000000004'::uuid::uuid) AND (u.body->'auto_targets'='true'::jsonb OR EXISTS(SELECT 1 FROM jsonb_array_elements(u.body->'targets') t WHERE t->>'id'='00000000-0000-4000-8000-000000000005'::uuid::uuid::text))) OR EXISTS(SELECT 1 FROM mobile_usage_scopes m WHERE m.usage_id=u.id AND m.device_id='00000000-0000-4000-8000-000000000004'::uuid AND m.target_id='00000000-0000-4000-8000-000000000005'::uuid)))) THEN RAISE EXCEPTION 'Existing usage must not fall back to binding-only authorization'; END IF;
 UPDATE mobile_usages SET state='paused' WHERE id='00000000-0000-4000-8000-000000000006'::uuid;
 IF EXISTS(SELECT to_jsonb(g) FROM mobile_v9_scope_grants g WHERE g.school_id='00000000-0000-4000-8000-000000000003'::uuid AND '00000000-0000-4000-8000-000000000004'::uuid=ANY(g.device_ids) AND ('00000000-0000-4000-8000-000000000005'::uuid=ANY(g.target_ids) OR g.auto_targets) AND ('production_allowlist'='production_allowlist' OR ((g.release_id IS NULL OR g.release_id=NULL::uuid) AND g.stage='production_allowlist')) AND ('00000000-0000-4000-8000-000000000007'::uuid::uuid IS NULL OR g.id='00000000-0000-4000-8000-000000000007'::uuid) AND g.expires_at>clock_timestamp() AND ('production_allowlist'<>'production_allowlist' OR EXISTS(SELECT 1 FROM mobile_usage_scopes us JOIN mobile_usages u ON u.id=us.usage_id WHERE us.scope_id=g.id AND u.approval='approved' AND u.state='active' AND u.expires_at>clock_timestamp() AND EXISTS(SELECT 1 FROM execution_devices ud JOIN mobile_device_target_bindings ub ON ub.device_id=ud.id JOIN mobile_targets ut ON ut.id=ub.target_id WHERE ud.id='00000000-0000-4000-8000-000000000004'::uuid AND ut.id='00000000-0000-4000-8000-000000000005'::uuid AND ub.school_id='00000000-0000-4000-8000-000000000003'::uuid AND us.resource_snapshot=jsonb_build_object('device_revision',ud.revision,'binding_locator_revision',ub.locator_revision,'target_locator_revision',CASE WHEN ub.search_text_override IS NULL THEN ut.locator_revision ELSE NULL END,'search_text',coalesce(ub.search_text_override,ut.search_text))))) AND NOT EXISTS(SELECT 1 FROM mobile_v9_scope_revocations r WHERE r.grant_id=g.id) AND (NOT (g.resource_revisions ? '00000000-0000-4000-8000-000000000004'::uuid::uuid::text) OR (g.resource_revisions->>'00000000-0000-4000-8000-000000000004'::uuid::uuid::text)::bigint=coalesce((SELECT revision FROM mobile_shared_school_access WHERE device_id='00000000-0000-4000-8000-000000000004'::uuid AND school_id='00000000-0000-4000-8000-000000000003'::uuid AND enabled),0)) ORDER BY g.created_at DESC,g.id DESC LIMIT 1) THEN RAISE EXCEPTION 'Paused scope remained effective'; END IF;
 UPDATE mobile_usages SET state='active' WHERE id='00000000-0000-4000-8000-000000000006'::uuid;
 UPDATE mobile_targets SET locator_revision=locator_revision+1 WHERE id='00000000-0000-4000-8000-000000000005'::uuid;
 IF EXISTS(SELECT to_jsonb(g) FROM mobile_v9_scope_grants g WHERE g.school_id='00000000-0000-4000-8000-000000000003'::uuid AND '00000000-0000-4000-8000-000000000004'::uuid=ANY(g.device_ids) AND ('00000000-0000-4000-8000-000000000005'::uuid=ANY(g.target_ids) OR g.auto_targets) AND ('production_allowlist'='production_allowlist' OR ((g.release_id IS NULL OR g.release_id=NULL::uuid) AND g.stage='production_allowlist')) AND ('00000000-0000-4000-8000-000000000007'::uuid::uuid IS NULL OR g.id='00000000-0000-4000-8000-000000000007'::uuid) AND g.expires_at>clock_timestamp() AND ('production_allowlist'<>'production_allowlist' OR EXISTS(SELECT 1 FROM mobile_usage_scopes us JOIN mobile_usages u ON u.id=us.usage_id WHERE us.scope_id=g.id AND u.approval='approved' AND u.state='active' AND u.expires_at>clock_timestamp() AND EXISTS(SELECT 1 FROM execution_devices ud JOIN mobile_device_target_bindings ub ON ub.device_id=ud.id JOIN mobile_targets ut ON ut.id=ub.target_id WHERE ud.id='00000000-0000-4000-8000-000000000004'::uuid AND ut.id='00000000-0000-4000-8000-000000000005'::uuid AND ub.school_id='00000000-0000-4000-8000-000000000003'::uuid AND us.resource_snapshot=jsonb_build_object('device_revision',ud.revision,'binding_locator_revision',ub.locator_revision,'target_locator_revision',CASE WHEN ub.search_text_override IS NULL THEN ut.locator_revision ELSE NULL END,'search_text',coalesce(ub.search_text_override,ut.search_text))))) AND NOT EXISTS(SELECT 1 FROM mobile_v9_scope_revocations r WHERE r.grant_id=g.id) AND (NOT (g.resource_revisions ? '00000000-0000-4000-8000-000000000004'::uuid::uuid::text) OR (g.resource_revisions->>'00000000-0000-4000-8000-000000000004'::uuid::uuid::text)::bigint=coalesce((SELECT revision FROM mobile_shared_school_access WHERE device_id='00000000-0000-4000-8000-000000000004'::uuid AND school_id='00000000-0000-4000-8000-000000000003'::uuid AND enabled),0)) ORDER BY g.created_at DESC,g.id DESC LIMIT 1) THEN RAISE EXCEPTION 'Changed target locator retained authorization'; END IF;
END $$;
ROLLBACK;
